/**
 * 发单页面逻辑 - 帮到位校园互助小程序
 * 功能：发布互助需求表单，包含表单验证与提交
 * 数据来源：云函数 createOrder
 */

var commonUtil = require('../../utils/common-util.js')

Page({
  /**
   * 页面的初始数据
   */
  data: {
    // 宿舍楼栋（手写输入）
    building: '',
    // 楼层
    floor: '',
    // 房间号
    room: '',
    // 联系方式（手机号）
    phone: '',
    // 自动填充的手机号（从用户信息读取）
    userPhone: '',
    // 水桶数量，默认1
    count: 1,
    // 报酬金额
    price: '',
    // 备注
    remark: '',
    // 期望送达日期
    deliveryDate: '',
    // 期望送达时间
    deliveryTime: '',
    // 代课专属字段
    classDate: '',
    classSection: '',
    className: '',
    classLocation: '',
    // 备注placeholder
    remarkPlaceholder: '如：请在17:00前送达，加钱请双方自行协商',
    // 是否正在提交
    submitting: false,
    // 价格选项列表
    priceOptions: [],
    // 价格提示文字
    priceHint: '',
    // 编辑模式标识
    editMode: false,
    // 编辑的订单ID
    editOrderId: '',
    // 分类列表
    categoryList: [
      { id: 'water', name: '搬水', icon: '\uD83D\uDCA7' },
      { id: 'errand', name: '跑腿', icon: '\uD83C\uDFC3' },
      { id: 'substitute', name: '代课', icon: '\uD83D\uDCDA' },
      { id: 'secondhand', name: '二手', icon: '\uD83D\uDECD' },
      { id: 'other', name: '其他', icon: '\u2753' }
    ],
    categoryIndex: 0,
    selectedCategory: 'water',
    // 配送方式（二手分类）：pickup=仅自取，deliver=可配送
    deliveryMethod: 'pickup',
    // 商品图片（二手分类）
    productImages: [],
    // 搬水桶数
    waterBucketCount: 1,
    // 其他分类图片
    otherImages: [],
    otherImageCount: 0
  },

  /**
   * 页面加载
   */
  onLoad: function (options) {
    // onLoad 对 tabBar 页面只在首次调用
    // 编辑模式通过 onShow 检查缓存实现
  },

  /**
   * 页面显示（每次进入都触发，包括switchTab）
   * 检查是否有编辑缓存的订单数据
   */
  onShow: function () {
    if (typeof this.getTabBar === 'function' && this.getTabBar()) {
      this.getTabBar().setData({ selected: 2 })
    }
    var that = this

    // 从缓存读取用户手机号，自动填充
    var userInfoStr = wx.getStorageSync('userInfo') || ''
    var userInfo = {}
    if (userInfoStr) {
      try { userInfo = JSON.parse(userInfoStr) } catch (e) {}
    }
    that.setData({
      userPhone: userInfo.phone || ''
    })

    if (!that.data.deliveryDate) {
      var now = new Date()
      var year = now.getFullYear()
      var month = String(now.getMonth() + 1).padStart(2, '0')
      var day = String(now.getDate()).padStart(2, '0')
      var defaultDate = year + '-' + month + '-' + day
      var defaultHour = String(Math.min(now.getHours() + 2, 23)).padStart(2, '0')
      var defaultTime = defaultHour + ':00'
      that.setData({
        deliveryDate: defaultDate,
        deliveryTime: defaultTime
      })
    }

    // 如果已经在编辑模式，不需要重复加载
    if (that.data.editMode) return

    var editOrderCache = wx.getStorageSync('editOrder')
    if (editOrderCache) {
      try {
        var editData = JSON.parse(editOrderCache)
        that.setData({
          building: editData.building || '',
          floor: editData.floor || '',
          room: editData.room || '',
          phone: editData.phone || '',
          count: editData.count || 1,
          price: editData.price || '',
          remark: editData.remark || '',
          deliveryTime: editData.deliveryTime || '',
          editMode: true,
          editOrderId: editData.id || ''
        })
        // 拆分 deliveryTime 为日期和时间
        if (editData.deliveryTime) {
          var parts = editData.deliveryTime.split(' ')
          if (parts.length === 2) {
            that.setData({
              deliveryDate: parts[0],
              deliveryTime: parts[1]
            })
          }
        }
        // 清除缓存，避免下次进入重复加载
        wx.removeStorageSync('editOrder')
      } catch (e) {
        wx.removeStorageSync('editOrder')
      }
    }
  },

  /**
   * 二手分类 - 选择仅自取
   */
  selectPickup: function () {
    this.setData({ deliveryMethod: 'pickup' })
  },

  /**
   * 二手分类 - 选择可配送
   */
  selectDeliver: function () {
    var that = this
    wx.showModal({
      title: '可配送说明',
      content: '选择"可配送"表示您愿意将物品送货给买家，由您（发布者）直接送达给收货者，中间不经过第三方。运费建议双方协商。',
      showCancel: false,
      confirmText: '我知道了',
      success: function() {
        that.setData({ deliveryMethod: 'deliver' })
      }
    })
  },

  /**
   * 分类选择事件
   */
  onCategorySelect: function (e) {
    var index = e.currentTarget.dataset.index
    var cat = this.data.categoryList[index]
    var placeholder = ''
    if (cat.id === 'substitute') {
      placeholder = '如：要求女生 / 需要会做实验 / 请准时到达，不要迟到'
    } else if (cat.id === 'errand') {
      placeholder = '如：请帮忙取菜鸟驿站快递 / 代买午饭到5栋楼下'
    } else if (cat.id === 'secondhand') {
      placeholder = '如：九成新 / 买了两个月 / 可以小刀'
    } else if (cat.id === 'other') {
      placeholder = '请详细描述你的需求，方便同学了解'
    } else {
      placeholder = '如：请在17:00前送达，加钱请双方自行协商'
    }
    this.setData({
      categoryIndex: index,
      selectedCategory: cat.id,
      remarkPlaceholder: placeholder,
      deliveryMethod: 'pickup',
      priceOptions: [],
      priceHint: '',
      price: '',
      otherImages: [],
      otherImageCount: 0
    })
  },

  /**
   * 宿舍楼栋输入事件
   */
  bindBuildingInput: function (e) {
    var val = e.detail.value.replace(/[^0-9a-zA-Z]/g, '')
    this.setData({ building: val })
  },

  /**
   * 楼层输入事件
   */
  bindFloorInput: function (e) {
    var that = this
    var floor = parseInt(e.detail.value) || 0
    var options = []
    var hint = ''

    // 跑腿/代课/二手/其他分类不根据楼层推荐金额
    if (that.data.selectedCategory === 'errand' || that.data.selectedCategory === 'substitute' || that.data.selectedCategory === 'secondhand' || that.data.selectedCategory === 'other') {
      that.setData({
        floor: e.detail.value,
        priceOptions: [],
        priceHint: '',
        price: ''
      })
      return
    }

    // 搬水分类：计算楼层单价
    var unitPrice = 0
    if (floor <= 0) {
      options = []
      hint = '请先输入楼层'
    } else if (floor <= 3) {
      unitPrice = 2
      options = [2]
      hint = '1-3楼统一价2元'
    } else if (floor === 4) {
      unitPrice = 2.5
      options = [2.5, 3]
      hint = '4楼建议价2.5-3元'
    } else if (floor === 5) {
      unitPrice = 3
      options = [3, 3.5, 4]
      hint = '5楼建议价3-4元'
    } else if (floor === 6) {
      unitPrice = 4
      options = [4, 4.5, 5]
      hint = '6楼建议价4-5元'
    } else {
      unitPrice = 5
      options = [5, 6, 7]
      hint = '7楼以上建议价5-7元'
    }

    // 搬水价格 = 楼层单价 x 桶数
    var bucketCount = that.data.count || 1
    var totalPrice = unitPrice * bucketCount

    // priceOptions 中的每个选项也需要乘以桶数
    var priceOptionsWithBucket = options.map(function(opt) { return opt * bucketCount })

    that.setData({
      floor: e.detail.value,
      priceOptions: priceOptionsWithBucket,
      priceHint: hint + (floor > 0 ? '（' + bucketCount + '桶 x ' + unitPrice + '元 = ' + totalPrice + '元）' : ''),
      price: priceOptionsWithBucket.length === 1 ? String(totalPrice) : ''
    })
  },

  /**
   * 价格选项点击事件
   */
  onPriceSelect: function (e) {
    var price = e.currentTarget.dataset.price
    this.setData({ price: String(price) })
  },

  /**
   * 房间号输入事件
   */
  bindRoomInput: function (e) {
    this.setData({
      room: e.detail.value
    })
  },

  /**
   * 手机号输入事件
   */
  bindPhoneInput: function (e) {
    this.setData({
      userPhone: e.detail.value
    })
  },

  /**
   * 报酬金额输入事件
   */
  bindPriceInput: function (e) {
    this.setData({
      price: e.detail.value
    })
  },

  /**
   * 备注输入事件
   */
  bindRemarkInput: function (e) {
    this.setData({
      remark: e.detail.value
    })
  },

  /**
   * 期望送达日期选择事件
   */
  bindDeliveryDateChange: function (e) {
    this.setData({
      deliveryDate: e.detail.value
    })
  },
  /**
   * 期望送达时间选择事件
   */
  bindDeliveryTimeChange: function (e) {
    this.setData({
      deliveryTime: e.detail.value
    })
  },

  /**
   * 上课日期选择事件
   */
  bindClassDateChange: function (e) {
    this.setData({ classDate: e.detail.value })
  },
  /**
   * 上课节次输入事件
   */
  bindClassSectionInput: function (e) {
    this.setData({ classSection: e.detail.value })
  },
  /**
   * 课程名称输入事件
   */
  bindClassNameInput: function (e) {
    this.setData({ className: e.detail.value })
  },
  /**
   * 上课地点输入事件
   */
  bindClassLocationInput: function (e) {
    this.setData({ classLocation: e.detail.value })
  },

  /**
   * 水桶数量 - 减少
   */
  minusCount: function () {
    if (this.data.count > 1) {
      this.setData({ count: this.data.count - 1 })
      this.recalcWaterPrice()
    }
  },

  /**
   * 水桶数量 - 增加
   */
  plusCount: function () {
    if (this.data.count < 5) {
      this.setData({ count: this.data.count + 1 })
      this.recalcWaterPrice()
    }
  },

  // 重新计算搬水价格
  recalcWaterPrice: function() {
    var that = this
    var floor = parseInt(that.data.floor) || 0
    if (floor <= 0 || that.data.selectedCategory !== 'water') return
    var unitPrice = 0
    if (floor <= 3) unitPrice = 2
    else if (floor === 4) unitPrice = 2.5
    else if (floor === 5) unitPrice = 3
    else if (floor === 6) unitPrice = 4
    else unitPrice = 5
    var bucketCount = that.data.count || 1
    var totalPrice = unitPrice * bucketCount
    var hint = ''
    if (floor <= 3) hint = '1-3楼统一价2元'
    else if (floor === 4) hint = '4楼建议价2.5-3元'
    else if (floor === 5) hint = '5楼建议价3-4元'
    else if (floor === 6) hint = '6楼建议价4-5元'
    else hint = '7楼以上建议价5-7元'
    that.setData({
      priceHint: hint + '（' + bucketCount + '桶 x ' + unitPrice + '元 = ' + totalPrice + '元）',
      price: String(totalPrice)
    })
  },

  /**
   * 桶数输入事件（搬水分类）
   */
  bindWaterBucket: function (e) {
    var that = this
    var bucketCount = that.data.count || 1
    that.setData({ waterBucketCount: bucketCount })

    // 重新计算价格
    var floor = parseInt(that.data.floor) || 0
    if (floor > 0 && that.data.selectedCategory === 'water') {
      var unitPrice = 0
      if (floor <= 3) unitPrice = 2
      else if (floor === 4) unitPrice = 2.5
      else if (floor === 5) unitPrice = 3
      else if (floor === 6) unitPrice = 4
      else unitPrice = 5

      var totalPrice = unitPrice * bucketCount
      var hint = ''
      if (floor <= 3) hint = '1-3楼统一价2元'
      else if (floor === 4) hint = '4楼建议价2.5-3元'
      else if (floor === 5) hint = '5楼建议价3-4元'
      else if (floor === 6) hint = '6楼建议价4-5元'
      else hint = '7楼以上建议价5-7元'

      that.setData({
        priceHint: hint + '（' + bucketCount + '桶 x ' + unitPrice + '元 = ' + totalPrice + '元）',
        price: String(totalPrice)
      })
    }
  },

  /**
   * 提交表单
   * 包含完整的表单验证逻辑，验证通过后调用云函数创建订单
   */
  onSubmit: function () {
    var that = this

    // 检查手机号
    var cachedUser = wx.getStorageSync('userInfo')
    try { cachedUser = JSON.parse(cachedUser) } catch(e) { cachedUser = {} }
    if (!cachedUser.phone || cachedUser.phone.length !== 11) {
      wx.showModal({
        title: '需要填写手机号',
        content: '发布订单需要先填写手机号码',
        confirmText: '去填写',
        success: function (modalRes) {
          if (modalRes.confirm) {
            wx.navigateTo({ url: '/pages/edit-profile/edit-profile' })
          }
        }
      })
      return
    }

    var building = (that.data.building || '').trim()
    var floor = that.data.floor
    var room = that.data.room
    var phone = that.data.userPhone || ''
    var count = that.data.count
    var price = that.data.price
    var remark = that.data.remark
    var selectedCategory = that.data.selectedCategory

    // ===== 表单验证 =====

    // 验证手机号（所有分类都需要）
    var phoneReg = /^1[2-9]\d{9}$/
    if (!phone || !phoneReg.test(phone)) {
      wx.showToast({ title: '请输入正确的11位手机号', icon: 'none' })
      return
    }

    // 搬水、跑腿分类：需要楼栋、楼层、房间、金额、送达时间
    if (selectedCategory === 'water' || selectedCategory === 'errand') {
      if (!building) {
        wx.showToast({ title: '请输入宿舍楼栋', icon: 'none' })
        return
      }
      var floorNum = parseInt(floor)
      if (!floor || isNaN(floorNum) || floorNum < 1 || floorNum > 9) {
        wx.showToast({ title: '请输入有效楼层（1-9）', icon: 'none' })
        return
      }
      if (!room || room.trim() === '') {
        wx.showToast({ title: '请输入房间号', icon: 'none' })
        return
      }
      var priceNum = parseFloat(price)
      if (!price || isNaN(priceNum) || priceNum < 1 || priceNum > 20) {
        wx.showToast({ title: '报酬金额需在1-20元之间', icon: 'none' })
        return
      }
      if (!that.data.deliveryDate) {
        wx.showToast({ title: '请选择期望送达日期', icon: 'none' })
        return
      }
      if (!that.data.deliveryTime) {
        wx.showToast({ title: '请选择期望送达时间', icon: 'none' })
        return
      }
    }

    // 代课分类：不需要楼栋信息，需要课程信息
    if (selectedCategory === 'substitute') {
      if (!that.data.classDate) {
        wx.showToast({ title: '请选择上课日期', icon: 'none' })
        return
      }
      if (!that.data.classSection) {
        wx.showToast({ title: '请填写上课节次', icon: 'none' })
        return
      }
      if (!that.data.className) {
        wx.showToast({ title: '请填写课程名称', icon: 'none' })
        return
      }
      if (!that.data.classLocation) {
        wx.showToast({ title: '请填写上课地点', icon: 'none' })
        return
      }
      var priceNum = parseFloat(price)
      if (!price || isNaN(priceNum) || priceNum < 1 || priceNum > 20) {
        wx.showToast({ title: '报酬金额需在1-20元之间', icon: 'none' })
        return
      }
    }

    // 二手分类：不需要楼栋和送达时间，需要金额和描述
    if (selectedCategory === 'secondhand') {
      var priceNum = parseFloat(price)
      if (!price || isNaN(priceNum) || priceNum < 0 || priceNum > 1000) {
        wx.showToast({ title: '价格需在0-1000元之间', icon: 'none' })
        return
      }
      if (!remark || remark.trim() === '') {
        wx.showToast({ title: '请填写商品描述', icon: 'none' })
        return
      }
    }

    // 其他分类：需要描述
    if (selectedCategory === 'other') {
      if (!remark || remark.trim() === '') {
        wx.showToast({ title: '请填写需求描述', icon: 'none' })
        return
      }
    }

    // ===== 调用云函数提交订单 =====
    // 确保变量有默认值（其他分类可能没有经过完整验证）
    var floorNum = parseInt(floor) || 0
    var priceNum = parseFloat(price) || 0
    var deliveryDate = that.data.deliveryDate || ''
    var deliveryTimeOnly = that.data.deliveryTime || ''
    var deliveryTime = ''
    if (deliveryDate && deliveryTimeOnly) {
      deliveryTime = deliveryDate + ' ' + deliveryTimeOnly
    }

    that.setData({ submitting: true })

    // 编辑模式：通过云函数更新已有订单
    if (that.data.editMode) {
      wx.cloud.callFunction({
        name: 'updateOrder',
        data: {
          orderId: that.data.editOrderId,
          building: building,
          floor: floorNum,
          room: room.trim(),
          phone: phone,
          count: count,
          price: priceNum,
          remark: remark.trim(),
          deliveryTime: deliveryTime
        },
        success: function (res) {
          var result = res.result
          if (result.code === 0) {
            wx.showToast({ title: '修改成功', icon: 'success' })
            setTimeout(function () {
              // 清空表单和编辑状态
              that.setData({
                building: '', floor: '', room: '', phone: '',
                count: 1, price: '', remark: '', deliveryTime: '',
                priceOptions: [], priceHint: '',
                editMode: false, editOrderId: '', submitting: false,
                waterBucketCount: 1, otherImages: [], otherImageCount: 0
              })
              wx.switchTab({ url: '/pages/orders/orders' })
            }, 1500)
          } else {
            wx.showToast({ title: result.msg || '修改失败', icon: 'none' })
            that.setData({ submitting: false })
          }
        },
        fail: function (err) {
          console.error('[帮到位] updateOrder云函数失败', err)
          wx.showModal({
            title: '修改失败',
            content: err.errMsg || '网络错误，请重试',
            showCancel: false
          })
          that.setData({ submitting: false })
        }
      })
      return
    }

    // 构建订单数据
    var orderData = {
      building: building,
      floor: floorNum,
      room: room.trim(),
      phone: phone,
      count: count,
      price: priceNum,
      remark: remark.trim(),
      deliveryTime: deliveryTime,
      category: that.data.selectedCategory
    }

    // 代课专属字段
    if (selectedCategory === 'substitute') {
      orderData.classDate = that.data.classDate
      orderData.classSection = that.data.classSection
      orderData.className = that.data.className
      orderData.classLocation = that.data.classLocation
    }

    // 二手分类配送方式
    if (selectedCategory === 'secondhand') {
      orderData.deliveryMethod = that.data.deliveryMethod
    }

    // 二手分类需要先上传图片
    if (that.data.selectedCategory === 'secondhand' && that.data.productImages.length > 0) {
      that.uploadProductImages(orderData)
    } else if (that.data.selectedCategory === 'other' && that.data.otherImages.length > 0) {
      that.uploadOtherImages(orderData)
    } else {
      that.doCreateOrder(orderData)
    }
  },

  /**
   * 图片压缩（使用公共模块，压缩到100KB以内）
   */
  compressImage: function (filePath) {
    return commonUtil.compressImageToSize(filePath, 100)
  },

  uploadSingleImage: function (filePath, folder) {
    return new Promise(function(resolve) {
      wx.cloud.uploadFile({
        cloudPath: folder + '/' + Date.now() + '_' + Math.floor(Math.random() * 9999) + '.jpg',
        filePath: filePath,
        success: function (res) { resolve(res.fileID) },
        fail: function () { resolve('') }
      })
    })
  },

  /**
   * 上传商品图片（先压缩再上传）
   */
  uploadProductImages: function (orderData) {
    var that = this
    var images = that.data.productImages
    
    Promise.all(images.map(function(img) {
      return that.compressImage(img)
    })).then(function(compressedPaths) {
      return Promise.all(compressedPaths.map(function(path) {
        return that.uploadSingleImage(path, 'product-images')
      }))
    }).then(function(fileIDs) {
      var validIDs = []
      for (var j = 0; j < fileIDs.length; j++) {
        if (fileIDs[j]) validIDs.push(fileIDs[j])
      }
      orderData.productImages = validIDs
      that.doCreateOrder(orderData)
    })
  },

  /**
   * 上传其他分类图片（先压缩再上传）
   */
  uploadOtherImages: function (orderData) {
    var that = this
    var images = that.data.otherImages
    
    Promise.all(images.map(function(img) {
      return that.compressImage(img)
    })).then(function(compressedPaths) {
      return Promise.all(compressedPaths.map(function(path) {
        return that.uploadSingleImage(path, 'other-images')
      }))
    }).then(function(fileIDs) {
      var validIDs = []
      for (var j = 0; j < fileIDs.length; j++) {
        if (fileIDs[j]) validIDs.push(fileIDs[j])
      }
      orderData.otherImages = validIDs
      that.doCreateOrder(orderData)
    })
  },

  /**
   * 创建订单
   */
  doCreateOrder: function (orderData) {
    var that = this
    // 从缓存读取用户信息，传递 school 字段
    var userInfoStr = wx.getStorageSync('userInfo') || ''
    var userInfo = {}
    if (userInfoStr) {
      try { userInfo = JSON.parse(userInfoStr) } catch (e) {}
    }
    orderData.school = userInfo.school || ''
    wx.cloud.callFunction({
      name: 'createOrder',
      data: orderData,
      success: function (res) {
        var result = res.result
        if (result.code === 0) {
          // 请求订阅消息（接单通知）
          wx.requestSubscribeMessage({
            tmplIds: ['NN3zfnGZHRpc8S9UPGYG1nop3OSBwmQ5LCuSYlbxRfw'],
            complete: function () {}
          })
          wx.showToast({ title: '发布成功', icon: 'success' })
          setTimeout(function () {
            that.setData({
              building: '', floor: '', room: '', phone: '',
              count: 1, price: '', remark: '', deliveryTime: '',
              editMode: false, editOrderId: '', submitting: false,
              productImages: [], priceOptions: [], priceHint: '',
              categoryIndex: 0, selectedCategory: 'water',
              waterBucketCount: 1, otherImages: [], otherImageCount: 0
            })
            wx.switchTab({ url: '/pages/orders/orders' })
          }, 1500)
        } else {
          wx.showToast({ title: result.msg || '发布失败', icon: 'none' })
          that.setData({ submitting: false })
        }
      },
      fail: function () {
        wx.showToast({ title: '发布失败', icon: 'none' })
        that.setData({ submitting: false })
      }
    })
  },

  /**
   * 添加商品图片
   */
  addProductImage: function () {
    var that = this
    var remaining = 3 - that.data.productImages.length
    if (remaining <= 0) return

    wx.chooseImage({
      count: remaining,
      sizeType: ['compressed'],
      sourceType: ['album', 'camera'],
      success: function (res) {
        var newImages = that.data.productImages.concat(res.tempFilePaths)
        that.setData({ productImages: newImages })
      }
    })
  },

  /**
   * 删除商品图片
   */
  removeProductImage: function (e) {
    var index = e.currentTarget.dataset.index
    var images = this.data.productImages
    images.splice(index, 1)
    this.setData({ productImages: images })
  },

  /**
   * 预览商品大图
   */
  previewProductImage: function (e) {
    var url = e.currentTarget.dataset.url
    if (url) {
      wx.previewImage({ urls: this.data.productImages, current: url })
    }
  },

  previewOtherImage: function (e) {
    var url = e.currentTarget.dataset.url
    if (url) {
      wx.previewImage({ urls: this.data.otherImages, current: url })
    }
  },

  /**
   * 选择其他分类图片
   */
  chooseOtherImage: function () {
    var that = this
    var remaining = 3 - that.data.otherImages.length
    if (remaining <= 0) {
      wx.showToast({ title: '最多3张', icon: 'none' })
      return
    }
    wx.chooseImage({
      count: remaining,
      sizeType: ['compressed'],
      sourceType: ['album', 'camera'],
      success: function (res) {
        that.setData({ otherImages: that.data.otherImages.concat(res.tempFilePaths) })
      }
    })
  },

  /**
   * 删除其他分类图片
   */
  removeOtherImage: function (e) {
    var index = e.currentTarget.dataset.index
    var images = this.data.otherImages
    images.splice(index, 1)
    this.setData({ otherImages: images })
  },

  /**
   * 请求订阅消息通知（已集成到 doCreateOrder 成功回调中）
   */
  requestSubscribe: function () {
    wx.requestSubscribeMessage({
      tmplIds: ['NN3zfnGZHRpc8S9UPGYG1nop3OSBwmQ5LCuSYlbxRfw'],
      success: function (res) {
        console.log('[帮到位] 订阅消息授权结果', res)
      },
      fail: function (err) {
        console.log('[帮到位] 用户拒绝订阅消息或接口不可用', err)
      }
    })
  }
})
